<?php
session_start();
require_once './functions/admin.php';
require_once './functions/database_functions.php';
$conn = db_connect();
$title = 'Thống kê và báo cáo';

$selectedMonth = isset($_GET['month']) && preg_match('/^\d{4}-\d{2}$/', $_GET['month']) ? $_GET['month'] : date('Y-m');
$monthStart = $selectedMonth . '-01';
$nextMonth = date('Y-m', strtotime($monthStart . ' +1 month'));
$previousMonth = date('Y-m', strtotime($monthStart . ' -1 month'));
$monthStartEsc = mysqli_real_escape_string($conn, $monthStart);
$nextMonthEsc = mysqli_real_escape_string($conn, $nextMonth . '-01');
$validOrderSql = "order_status NOT IN ('đã_hủy','cancelled','đã hủy')";

function report_value($conn, $sql) {
  $result = mysqli_query($conn, $sql);
  if (!$result) return 0;
  $row = mysqli_fetch_row($result);
  return $row[0] ?? 0;
}
function report_money($value) { return number_format((float)$value, 0, ',', '.') . 'đ'; }

$revenue = report_value($conn, "SELECT COALESCE(SUM(amount),0) FROM orders WHERE date >= '$monthStartEsc' AND date < '$nextMonthEsc' AND $validOrderSql");
$orderCount = report_value($conn, "SELECT COUNT(*) FROM orders WHERE date >= '$monthStartEsc' AND date < '$nextMonthEsc'");
$soldCount = report_value($conn, "SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi INNER JOIN orders o ON o.orderid=oi.orderid WHERE o.date >= '$monthStartEsc' AND o.date < '$nextMonthEsc' AND o.$validOrderSql");
$averageOrder = $orderCount > 0 ? $revenue / $orderCount : 0;
$dailyLabels = $dailyRevenue = $dailyOrders = array();
$daysInMonth = (int)date('t', strtotime($monthStart));
for ($day = 1; $day <= $daysInMonth; $day++) { $dailyLabels[] = str_pad($day, 2, '0', STR_PAD_LEFT); $dailyRevenue[] = 0; $dailyOrders[] = 0; }
$dailyResult = mysqli_query($conn, "SELECT DAY(date) AS day, COALESCE(SUM(amount),0) AS revenue, COUNT(*) AS orders FROM orders WHERE date >= '$monthStartEsc' AND date < '$nextMonthEsc' AND $validOrderSql GROUP BY DAY(date) ORDER BY day");
if ($dailyResult) while ($row = mysqli_fetch_assoc($dailyResult)) { $index = (int)$row['day'] - 1; $dailyRevenue[$index] = (float)$row['revenue']; $dailyOrders[$index] = (int)$row['orders']; }

$topBooks = array();
$topResult = mysqli_query($conn, "SELECT b.book_title, SUM(oi.quantity) sold, SUM(oi.quantity * oi.item_price) revenue FROM order_items oi INNER JOIN books b ON b.book_isbn=oi.book_isbn INNER JOIN orders o ON o.orderid=oi.orderid WHERE o.date >= '$monthStartEsc' AND o.date < '$nextMonthEsc' AND o.$validOrderSql GROUP BY b.book_isbn,b.book_title ORDER BY sold DESC LIMIT 10");
if ($topResult) while ($row = mysqli_fetch_assoc($topResult)) $topBooks[] = $row;

$statusCounts = array('chờ_xử_lý'=>0, 'đang_giao'=>0, 'đã_giao'=>0, 'đã_hủy'=>0);
$statusResult = mysqli_query($conn, "SELECT order_status, COUNT(*) total FROM orders WHERE date >= '$monthStartEsc' AND date < '$nextMonthEsc' GROUP BY order_status");
if ($statusResult) while ($row = mysqli_fetch_assoc($statusResult)) {
  $status = $row['order_status'];
  if (in_array($status, array('pending','chờ_xử_lý'), true)) $statusCounts['chờ_xử_lý'] += (int)$row['total'];
  elseif (in_array($status, array('shipping','đang_giao'), true)) $statusCounts['đang_giao'] += (int)$row['total'];
  elseif (in_array($status, array('delivered','đã_giao'), true)) $statusCounts['đã_giao'] += (int)$row['total'];
  else $statusCounts['đã_hủy'] += (int)$row['total'];
}
require './template/header.php';
?>
<div class="report-shell"><aside class="report-sidebar"><div class="report-brand"><b>Nhà sách Việt Long</b><small>Quản trị viên</small></div><nav><a href="admin_dashboard.php"><i class="fa fa-chart-pie"></i>Dashboard</a><a href="admin_customer.php"><i class="fa fa-users"></i>Quản lý người dùng</a><a href="admin_book.php"><i class="fa fa-book"></i>Quản lý sách</a><a href="orders.php"><i class="fa fa-shopping-bag"></i>Quản lý đơn hàng</a><a href="admin_promotions.php"><i class="fa fa-tags"></i>Quản lý khuyến mãi</a><a class="active" href="admin_reports.php"><i class="fa fa-chart-column"></i>Thống kê và báo cáo</a></nav><a class="report-logout" href="admin_signout.php">Đăng xuất</a></aside><main class="report-main"><header class="report-header"><div><span>BÁO CÁO KINH DOANH</span><h1>Thống kê và báo cáo</h1><p>Theo dõi kết quả kinh doanh theo từng tháng.</p></div><form method="get" class="month-picker"><a href="?month=<?= $previousMonth ?>" title="Tháng trước"><i class="fa fa-chevron-left"></i></a><input type="month" name="month" value="<?= htmlspecialchars($selectedMonth) ?>" onchange="this.form.submit()"><a href="?month=<?= $nextMonth ?>" title="Tháng sau"><i class="fa fa-chevron-right"></i></a></form></header><section class="report-stats"><div><i class="fa fa-wallet"></i><small>Doanh thu tháng</small><strong><?= report_money($revenue) ?></strong></div><div><i class="fa fa-shopping-bag"></i><small>Tổng đơn hàng</small><strong><?= number_format($orderCount) ?></strong></div><div><i class="fa fa-book"></i><small>Sách đã bán</small><strong><?= number_format($soldCount) ?></strong></div><div><i class="fa fa-receipt"></i><small>Giá trị đơn trung bình</small><strong><?= report_money($averageOrder) ?></strong></div></section><section class="report-grid"><div class="report-card report-chart"><div class="report-card-head"><div><h2>Doanh thu theo ngày</h2><p>Tháng <?= date('m/Y', strtotime($monthStart)) ?></p></div><i class="fa fa-chart-line"></i></div><canvas id="reportChart" height="110"></canvas></div><div class="report-card"><div class="report-card-head"><div><h2>Trạng thái đơn hàng</h2><p>Trong tháng đã chọn</p></div><i class="fa fa-chart-pie"></i></div><div class="status-report"><div><span class="status-dot pending"></span>Chờ xử lý<strong><?= $statusCounts['chờ_xử_lý'] ?></strong></div><div><span class="status-dot shipping"></span>Đang giao<strong><?= $statusCounts['đang_giao'] ?></strong></div><div><span class="status-dot delivered"></span>Đã giao<strong><?= $statusCounts['đã_giao'] ?></strong></div><div><span class="status-dot cancelled"></span>Đã hủy<strong><?= $statusCounts['đã_hủy'] ?></strong></div></div></div></section><section class="report-card"><div class="report-card-head"><div><h2>Sách bán chạy trong tháng</h2><p>Tối đa 10 sản phẩm có số lượng bán cao nhất</p></div><i class="fa fa-ranking-star"></i></div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>#</th><th>Tên sách</th><th>Số lượng bán</th><th>Doanh thu</th></tr></thead><tbody><?php if (!$topBooks): ?><tr><td colspan="4" class="report-empty">Chưa có dữ liệu trong tháng này.</td></tr><?php else: foreach ($topBooks as $index => $book): ?><tr><td><b class="rank-badge"><?= $index + 1 ?></b></td><td><?= htmlspecialchars($book['book_title']) ?></td><td><?= number_format($book['sold']) ?> cuốn</td><td class="report-money"><?= report_money($book['revenue']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section></main></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('reportChart'),{type:'line',data:{labels:<?= json_encode($dailyLabels) ?>,datasets:[{label:'Doanh thu',data:<?= json_encode($dailyRevenue) ?>,borderColor:'#4f46e5',backgroundColor:'rgba(79,70,229,.12)',fill:true,tension:.35,yAxisID:'revenue'},{label:'Đơn hàng',data:<?= json_encode($dailyOrders) ?>,borderColor:'#f59e0b',backgroundColor:'transparent',tension:.35,yAxisID:'orders'}]},options:{responsive:true,interaction:{mode:'index',intersect:false},plugins:{tooltip:{callbacks:{label:function(context){return context.dataset.label+': '+(context.dataset.yAxisID==='revenue'?new Intl.NumberFormat('vi-VN').format(context.raw)+'đ':context.raw+' đơn');}}}},scales:{revenue:{beginAtZero:true,ticks:{callback:function(value){return new Intl.NumberFormat('vi-VN',{notation:'compact'}).format(value)+'đ';}}},orders:{beginAtZero:true,position:'right',grid:{drawOnChartArea:false},ticks:{precision:0}}});</script><style>.report-shell{display:flex;min-height:100vh;background:#f8fafc;color:#172033}.report-sidebar{position:fixed;inset:0 auto 0 0;width:250px;background:#20242b;color:#fff;padding:24px 14px;box-sizing:border-box}.report-brand{padding:0 10px 24px;border-bottom:1px solid #3b4149}.report-brand b,.report-brand small{display:block}.report-brand b{font-size:14px}.report-brand small{color:#aeb5bf;margin-top:4px}.report-sidebar nav{padding-top:20px}.report-sidebar nav a,.report-logout{display:flex;align-items:center;gap:11px;color:#bcc3cc;text-decoration:none;padding:12px 13px;border-radius:8px;margin-bottom:4px;font-size:13px}.report-sidebar nav a i{width:17px;text-align:center}.report-sidebar nav a:hover,.report-sidebar nav a.active{background:#343a43;color:#ffd45b}.report-logout{margin-top:auto;border-top:1px solid #3b4149;border-radius:0;padding-top:20px}.report-main{margin-left:250px;width:calc(100% - 250px);padding:34px;box-sizing:border-box}.report-header{display:flex;justify-